USE lyrica_platform;

-- Nạp thông tin 4 bài hát mẫu (uploaded_by = 1)
ON DUPLICATE KEY UPDATE
    title = VALUES(title),
    artist_name = VALUES(artist_name),
    cover_url = VALUES(cover_url),
    audio_url = VALUES(audio_url);

-- Xóa lời cũ của 4 bài (nếu có) trước khi nạp lại để tránh trùng dòng
DELETE FROM lyric_lines WHERE song_id IN (1, 2, 3, 4);

